// @connect      animeapi.my.id
// @grant        GM_xmlhttpRequest
// ==/UserScript==

this.AnimeAPI=class{_normalizeSource(source){const key=String(source).trim().toLowerCase();const map={ad:'anidb',adb:'anidb',anidb:'anidb','anidb.net':'anidb',al:'anilist',anilist:'anilist','anilist.co':'anilist',an:'animenewsnetwork',ann:'animenewsnetwork',animenewsnetwork:'animenewsnetwork','animenewsnetwork.com':'animenewsnetwork',ap:'animeplanet',animeplanet:'animeplanet','anime-planet':'animeplanet','anime-planet.com':'animeplanet','animeplanet.com':'animeplanet',as:'anisearch',anisearch:'anisearch','anisearch.com':'anisearch','anisearch.de':'anisearch','anisearch.it':'anisearch','anisearch.es':'anisearch','anisearch.fr':'anisearch','anisearch.jp':'anisearch',ac:'annict',anc:'annict',act:'annict',annict:'annict','annict.com':'annict','annict.jp':'annict','en.annict.com':'annict',hk:'hikka',hka:'hikka',hikka:'hikka','hikka.io':'hikka',im:'imdb',imdb:'imdb','imdb.com':'imdb',kz:'kaize',kaize:'kaize','kaize.io':'kaize',kt:'kitsu',kts:'kitsu',kitsu:'kitsu','kitsu.io':'kitsu','kitsu.app':'kitsu',lb:'letterboxd',lx:'letterboxd',letterboxd:'letterboxd','letterboxd.com':'letterboxd',lc:'livechart',livechart:'livechart','livechart.me':'livechart',ma:'myanimelist',mal:'myanimelist',myanimelist:'myanimelist','myanimelist.net':'myanimelist',nj:'nautiljon',ntj:'nautiljon',nautiljon:'nautiljon','nautiljon.com':'nautiljon',nf:'notify',ntf:'notify',ntm:'notify',notify:'notify',notifymoe:'notify','notify.moe':'notify',oo:'otakotaku',otakotaku:'otakotaku','otakotaku.com':'otakotaku',sh:'shikimori',shiki:'shikimori',shk:'shikimori',shikimori:'shikimori','shiki.one':'shikimori','shikimori.io':'shikimori','shikimori.me':'shikimori','shikimori.one':'shikimori','shikimori.org':'shikimori',sb:'shoboi',shb:'shoboi',syb:'shoboi',shoboi:'shoboi',shobocal:'shoboi',syoboi:'shoboi',syobocal:'shoboi','cal.syoboi.jp':'shoboi',sy:'silveryasha',silveryasha:'silveryasha',dbti:'silveryasha','db.silveryasha.id':'silveryasha','db.silveryasha.web.id':'silveryasha',sm:'simkl',smk:'simkl',simkl:'simkl','simkl.com':'simkl',animecountdown:'simkl','animecountdown.com':'simkl',tm:'themoviedb',tmdb:'themoviedb',themoviedb:'themoviedb','themoviedb.org':'themoviedb',tv:'thetvdb',tvdb:'thetvdb',thetvdb:'thetvdb','thetvdb.com':'thetvdb',tvtime:'thetvdb',tt:'thetvdb','tvtime.com':'thetvdb',tr:'trakt',trk:'trakt',trakt:'trakt','trakt.tv':'trakt'};return map[key]||key}_buildUrl(source,id){const canonical=this._normalizeSource(source);let idString=String(id);if(canonical==='thetvdb'&&!idString.toLowerCase().startsWith('series/')){idString=`series/${idString}`}const encodedId=idString.split('/').map(function(seg){return encodeURIComponent(seg)}).join('/');return`https://animeapi.my.id/${canonical}/${encodedId}`}fetch(source,id){if(!source)throw new Error('A source is required');if(!id)throw new Error('An ID is required');const url=this._buildUrl(source,id);return new Promise((resolve,reject)=>{GM_xmlhttpRequest({method:'GET',url:url,timeout:15e3,onload:response=>{if(response.status===404){resolve(null);return}if(response.status!==200){reject(new Error(`AnimeAPI request failed with status ${response.status}`));return}try{const data=JSON.parse(response.responseText);resolve(data)}catch{reject(new Error('Failed to parse AnimeAPI response'))}},onerror:()=>{reject(new Error('An error occurs while processing the request'))},ontimeout:()=>{reject(new Error('Request times out'))}})})}};
